class Solution:
    def findDuplicate(self, paths: List[str]) -> List[List[str]]:
        from collections import defaultdict
        content_map = defaultdict(list)
        for path_entry in paths:
            parts = path_entry.split()
            dir_path = parts[0]
            for f in parts[1:]:
                name, content = f.split("(")
                content = content[:-1]
                content_map[content].append(f"{dir_path}/{name}")
        return [group for group in content_map.values() if len(group) > 1]

class Solution {
public:
    vector<vector<string>> findDuplicate(vector<string>& paths) {
        unordered_map<string, vector<string>> contentMap;
        for (const string& p : paths) {
            stringstream ss(p);
            string dir, file;
            ss >> dir;
            while (ss >> file) {
                size_t l = file.find('(');
                string name = file.substr(0, l);
                string content = file.substr(l + 1, file.size() - l - 2);
                contentMap[content].push_back(dir + "/" + name);
            }
        }
        vector<vector<string>> res;
        for (const auto& pair : contentMap) {
            if (pair.second.size() > 1) {
                res.push_back(pair.second);
            }
        }
        return res;
    }
};

class Solution {
    public List<List<String>> findDuplicate(String[] paths) {
        Map<String, List<String>> contentMap = new HashMap<>();
        for (String p : paths) {
            String[] parts = p.split(" ");
            String dir = parts[0];
            for (int i = 1; i < parts.length; i++) {
                int idx = parts[i].indexOf('(');
                String name = parts[i].substring(0, idx);
                String content = parts[i].substring(idx + 1, parts[i].length() - 1);
                contentMap.computeIfAbsent(content, k -> new ArrayList<>()).add(dir + "/" + name);
            }
        }
        List<List<String>> res = new ArrayList<>();
        for (List<String> list : contentMap.values()) {
            if (list.size() > 1) res.add(list);
        }
        return res;
    }
}

/**
 * @param {string[]} paths
 * @return {string[][]}
