var findDuplicate = function(paths) {
    const contentMap = new Map();
    for (const p of paths) {
        const parts = p.split(" ");
        const dir = parts[0];
        for (let i = 1; i < parts.length; i++) {
            const idx = parts[i].indexOf("(");
            const name = parts[i].slice(0, idx);
            const content = parts[i].slice(idx + 1, parts[i].length - 1);
            if (!contentMap.has(content)) contentMap.set(content, []);
            contentMap.get(content).push(`${dir}/${name}`);
        }
    }
    const res = [];
    for (const list of contentMap.values()) {
        if (list.length > 1) res.push(list);
    }
    return res;
};
